  if (!result.success) {
    const problems = new Map<string, string>()
    for (const issue of result.error.issues) {
      const name = String(issue.path[0])
      if (!problems.has(name)) problems.set(name, issue.message)
    }
    const lines = [...problems].map(([name, message]) => `  ${name} ${message}`)
    throw new Error(`Invalid configuration (${problems.size} variable(s)):\n${lines.join('\n')}`)
  }

  const data = result.data
  return {
    port: data.PORT ?? 3000,
    databaseUrl: data.DATABASE_URL,
    logLevel: data.LOG_LEVEL ?? 'info',
    enableMetrics: data.ENABLE_METRICS ?? false,
    allowedOrigins: data.ALLOWED_ORIGINS ?? [],
    requestTimeoutMs: data.REQUEST_TIMEOUT_MS ?? 5000,
  }
}

